#================================================================================================================================================================
# Database creation
#================================================================================================================================================================
CREATE DATABASE HealthPlus;
USE HealthPLus;

#==================================================================================================================================================================
# Table creation and insertion of values
#==================================================================================================================================================================
CREATE TABLE Clinics(
clinic_id varchar(6) not null,
clinic_name varchar(50) not null,
clinic_type varchar(50) not null,
city varchar(50) not null,
state varchar(50) not null,
established_year int not null,
contact_number varchar(15) not null,

CONSTRAINT pk_clinic_id PRIMARY KEY(clinic_id)

);


CREATE TABLE Specialists(
specialist_id varchar(6),
first_name varchar(50) not null,
last_name varchar(50) not null,
gender varchar(20) not null,
specialization varchar(50) not null,
clinic_id varchar(6) not null,
qualification varchar(50) not null,
experience_years int not null,
consultation_fee decimal(12,2) not null,

CONSTRAINT pk_specialist_id PRIMARY KEY(specialist_id),
CONSTRAINT fk_specialists_clinic FOREIGN KEY(clinic_id) REFERENCES Clinics(clinic_id)

);


CREATE TABLE Members(
member_id varchar(10) not null,
first_name varchar(50) not null,
last_name varchar(50) not null,
gender varchar(50) not null,
date_of_birth DATE not null,
age tinyint unsigned not null, # unsigned cannot include negative number eg: age tinyint unsigned not null,
city varchar(50) not null,
membership_type varchar(50) not null,
registration_date date not null,
phone_number varchar(20) not null,
email varchar(100) not null,

CONSTRAINT pk_member_id PRIMARY KEY(member_id)

);
ALTER TABLE Members MODIFY COLUMN member_id varchar(10) NOT NULL;
ALTER TABLE Members MODIFY COLUMN email varchar(100);
DESCRIBE Members;


CREATE TABLE Corporates (
    corporate_id VARCHAR(6) not null ,
    company_name VARCHAR(100) NOT NULL,
    industry VARCHAR(100) NOT NULL,
    city VARCHAR(50) NOT NULL,
    contract_start_date DATE NOT NULL,
    contract_end_date DATE NOT NULL,
    employee_count INT NOT NULL,
    
    CONSTRAINT pk_corporate_id PRIMARY KEY(corporate_id)
);


CREATE TABLE Corporate_Members (
    corporate_member_id VARCHAR(12) NOT NULL,
    corporate_id VARCHAR(6) NOT NULL,
    member_id VARCHAR(10) NOT NULL,
    designation VARCHAR(50) NOT NULL,
    enrollment_date DATE NOT NULL,
    
    CONSTRAINT pk_corporate_member_id PRIMARY KEY(corporate_member_id),
    CONSTRAINT fk_corp_members_corporate FOREIGN KEY (corporate_id) REFERENCES Corporates(corporate_id),
    CONSTRAINT fk_corp_members_member FOREIGN KEY (member_id) REFERENCES Members(member_id)
);


CREATE TABLE Consultations (
    consultation_id VARCHAR(12) not null,
    member_id VARCHAR(10) NOT NULL,
    specialist_id VARCHAR(10),
    clinic_id VARCHAR(10) NOT NULL,
    consultation_date DATE NOT NULL,
    consultation_mode VARCHAR(30) NOT NULL,
    status VARCHAR(30) NOT NULL,
    reason_for_visit VARCHAR(150) NOT NULL,
    
    CONSTRAINT pk_consultation_id  PRIMARY KEY(consultation_id),
    CONSTRAINT fk_consultations_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_consultations_specialist FOREIGN KEY (specialist_id) REFERENCES Specialists(specialist_id),
    CONSTRAINT fk_consultations_clinic FOREIGN KEY (clinic_id) REFERENCES Clinics(clinic_id)
);


CREATE TABLE Telemedicine_Sessions (
    session_id VARCHAR(12) not null,
    consultation_id VARCHAR(12) NOT NULL,
    session_start_time DATETIME NOT NULL,
    session_end_time DATETIME NOT NULL,
    platform VARCHAR(30) NOT NULL,
    connection_quality VARCHAR(30) NOT NULL,
    session_status VARCHAR(30) NOT NULL,
    
    CONSTRAINT pk_session_id  PRIMARY KEY(session_id),
    CONSTRAINT fk_telemed_consultation FOREIGN KEY (consultation_id) REFERENCES Consultations(consultation_id)
);


CREATE TABLE Chronic_Care_Programs (
    program_id VARCHAR(12) not null,
    member_id VARCHAR(10) NOT NULL,
    specialist_id VARCHAR(10) NOT NULL,
    condition_name VARCHAR(100) NOT NULL,
    enrollment_date DATE NOT NULL,
    program_status VARCHAR(30) NOT NULL,
    next_review_date DATE NOT NULL,
    
    CONSTRAINT pk_program_id  PRIMARY KEY(program_id),
    CONSTRAINT fk_chronic_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_chronic_specialist FOREIGN KEY (specialist_id) REFERENCES Specialists(specialist_id)
);


CREATE TABLE Health_Packages (
    package_id VARCHAR(10) not null,
    package_name VARCHAR(100) NOT NULL,
    package_type VARCHAR(50) NOT NULL,
    price DECIMAL(10,2) NOT NULL,
    validity_days INT NOT NULL,
    tests_included INT NOT NULL,
    
    CONSTRAINT pk_package_id  PRIMARY KEY(package_id)
);


CREATE TABLE Package_Subscriptions (
    subscription_id VARCHAR(12) not null,
    member_id VARCHAR(10) NOT NULL,
    package_id VARCHAR(10) NOT NULL,
    subscription_date DATE NOT NULL,
    expiry_date DATE NOT NULL,
    payment_status VARCHAR(30) NOT NULL,
    
    CONSTRAINT pk_subscrip_tionid  PRIMARY KEY(subscription_id),
    CONSTRAINT fk_subscriptions_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_subscriptions_package FOREIGN KEY (package_id) REFERENCES Health_Packages(package_id)
);


CREATE TABLE Prescriptions (
    prescription_id VARCHAR(12) NOT NULL,
    consultation_id VARCHAR(12) NOT NULL,
    member_id VARCHAR(10) NOT NULL,
    specialist_id VARCHAR(10) NOT NULL,
    medicine_name VARCHAR(150) NOT NULL,
    dosage VARCHAR(100) NOT NULL,
    duration_days INT NOT NULL,
    prescribed_date DATE NOT NULL,
    
    CONSTRAINT pk_prescription_id  PRIMARY KEY(prescription_id),
    CONSTRAINT fk_prescriptions_consultation FOREIGN KEY (consultation_id) REFERENCES Consultations(consultation_id),
    CONSTRAINT fk_prescriptions_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_prescriptions_specialist FOREIGN KEY (specialist_id) REFERENCES Specialists(specialist_id)
);


CREATE TABLE Lab_Tests (
    lab_test_id VARCHAR(12) not null,
    member_id VARCHAR(10) NOT NULL,
    clinic_id VARCHAR(10) NOT NULL,
    test_name VARCHAR(100) NOT NULL,
    test_date DATE NOT NULL,
    test_result VARCHAR(100) NOT NULL,
    test_cost DECIMAL(10,2) NOT NULL,
    test_status VARCHAR(30) NOT NULL,
    
    CONSTRAINT pk_lab_test_id  PRIMARY KEY(lab_test_id),
    CONSTRAINT fk_lab_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_lab_clinic FOREIGN KEY (clinic_id) REFERENCES Clinics(clinic_id)
);


CREATE TABLE Claims (
    claim_id VARCHAR(12) NOT NULL,
    member_id VARCHAR(10) NOT NULL,
    consultation_id VARCHAR(12),
    claim_amount DECIMAL(12,2) NOT NULL,
    claim_date DATE NOT NULL,
    claim_status VARCHAR(30) NOT NULL,
    insurance_provider VARCHAR(100),
    
    CONSTRAINT pk_claim_id  PRIMARY KEY(claim_id),
    CONSTRAINT fk_claims_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_claims_consultation FOREIGN KEY (consultation_id) REFERENCES Consultations(consultation_id)
);


CREATE TABLE Staff (
    staff_id VARCHAR(12),
    clinic_id VARCHAR(10) NOT NULL,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    designation VARCHAR(100) NOT NULL,
    employment_type VARCHAR(30) NOT NULL,
    salary DECIMAL(12,2) NOT NULL,
    joining_date DATE NOT NULL,
    
    CONSTRAINT pk_staff_id  PRIMARY KEY(staff_id),
    CONSTRAINT fk_staff_clinic FOREIGN KEY (clinic_id) REFERENCES Clinics(clinic_id)
);


CREATE TABLE Billing (
    bill_id VARCHAR(12) NOT NULL,
    member_id VARCHAR(10) NOT NULL,
    consultation_id VARCHAR(12),
    bill_date DATE NOT NULL,
    consultation_charges DECIMAL(12,2) NOT NULL,
    lab_charges DECIMAL(12,2) NOT NULL,
    medicine_charges DECIMAL(12,2) NOT NULL,
    total_amount DECIMAL(12,2) NOT NULL,
    bill_status VARCHAR(30) NOT NULL,
    
    CONSTRAINT pk_bill_id  PRIMARY KEY(bill_id),
    CONSTRAINT fk_billing_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_billing_consultation FOREIGN KEY (consultation_id) REFERENCES Consultations(consultation_id)
);


CREATE TABLE Payments (
    payment_id VARCHAR(12) NOT NULL,
    bill_id VARCHAR(12) NOT NULL,
    member_id VARCHAR(10) NOT NULL,
    payment_date DATE NOT NULL,
    payment_amount DECIMAL(12,2) NOT NULL,
    payment_mode VARCHAR(30),
    payment_status VARCHAR(30) NOT NULL,
    
    CONSTRAINT pk_payment_id  PRIMARY KEY(payment_id),
    CONSTRAINT fk_payments_bill FOREIGN KEY (bill_id) REFERENCES Billing(bill_id),
    CONSTRAINT fk_payments_member FOREIGN KEY (member_id) REFERENCES Members(member_id)
);


CREATE TABLE Feedback (
    feedback_id VARCHAR(12) NOT NULL,
    member_id VARCHAR(10) NOT NULL,
    consultation_id VARCHAR(12) NOT NULL,
    rating INT NOT NULL,
    feedback_text VARCHAR(255) NOT NULL,
    feedback_date DATE NOT NULL,
    
    CONSTRAINT pk_feedback PRIMARY KEY(feedback_id),
    CONSTRAINT fk_feedback_member FOREIGN KEY (member_id) REFERENCES Members(member_id),
    CONSTRAINT fk_feedback_consultation FOREIGN KEY (consultation_id) REFERENCES Consultations(consultation_id)
);



#====================================================================================================================================================================================================
# Data Profiling
#===========================================================================================================================================================================================================
# 1. Members - gender is in different format
SELECT distinct gender from Members;


# 2. Members - email has blanks
SELECT * from Members where email is null;

# 3. Members - emails are in different formats
SELECT * from Members where email not like '%@%.%';

# 4. Claims - consultation_id is blank
SELECT * from Claims where consultation_id is null;

# 5. Claims - insurance_provider is blank
SELECT * from Claims where insurance_provider is null;

# 6. Billing - consultation_id is blank
SELECT * from Billing where consultation_id is null;

# 7. Payments - Payment_mode is blank
SELECT * FROM Payments where payment_mode is null;

#==================================================================================================================================
# Data Cleaning
#=======================================================================================================================================

# 1, Members - gender is in different format
UPDATE Members
set gender=
CASE
WHEN lower(trim(gender)) in ('male','m')
THEN 'Male'
WHEN lower(trim(gender)) in ('female','f')
THEN 'Female'
ELSE gender
END;

set sql_safe_updates=0;

# 3. Members - email is in different format 
update Members 
set email=
CASE
WHEN email like '%gmail' and email not like '%@%'
THEN REPLACE(email,'gmail','@gmail')
END
where email not like '%@%.%';


#=======================================================================================================================================
#Data analysis
#================================================================================================================================================


#1. What is the total number of members, and how are they distributed across membership types and gender?
select membership_type,gender,count(*)
from Members
group by membership_type,gender
order by count(member_id) desc;

#2.Which cities have the highest number of members?
SELECT city,COUNT(*) AS total_members
FROM Members
GROUP BY city
ORDER BY total_members DESC;

#3. What is the total revenue generated, average bill value, and contribution of consultation, laboratory and medicine charges?
SELECT
COUNT(*) AS total_bills,
ROUND(SUM(total_amount), 2) AS total_revenue,
ROUND(AVG(total_amount), 2) AS average_bill_value,
ROUND(SUM(consultation_charges), 2) AS consultation_revenue,
ROUND(SUM(lab_charges), 2) AS lab_revenue,
ROUND(SUM(medicine_charges), 2) AS medicine_revenue
FROM Billing;

# 4. How many specialists are there?
SELECT COUNT(*) AS Total_no_of_Specialists
FROM Specialists;

# 5. What is the total revenue generated from billing?
SELECT SUM(total_amount) AS Total_Revenue
FROM Billing;

#6. What is the highest and lowest billing amount?
SELECT 
MAX(total_amount) AS Highest_Bill,
MIN(total_amount) AS Lowest_Bill
FROM Billing;

#7. How many members are there in each membership type?
SELECT membership_type,COUNT(member_id) AS Total_Members
FROM Members
GROUP BY membership_type;

#8. How many consultations are there for each consultation mode?
SELECT consultation_mode,COUNT(consultation_id) AS Total_Consultations
FROM Consultations
GROUP BY consultation_mode;

#9. How many consultations are there for each consultation status?
SELECT status,COUNT(consultation_id) AS Total_Consultations
FROM Consultations
GROUP BY status;

#10. Which specializations have more than 100 consultations?
SELECT s.specialization,COUNT(c.consultation_id) AS Total_Consultations
FROM Specialists s
INNER JOIN Consultations c
ON s.specialist_id = c.specialist_id
GROUP BY s.specialization
HAVING COUNT(c.consultation_id) > 100
ORDER BY Total_Consultations DESC;

#11. Which are the top 5 clinics based on number of consultations?
SELECT cl.clinic_name, COUNT(c.consultation_id) AS Total_Consultations
FROM Clinics cl
INNER JOIN Consultations c ON cl.clinic_id = c.clinic_id
GROUP BY cl.clinic_name
ORDER BY Total_Consultations DESC
LIMIT 5;

#12. Rank specialists based on consultation fee from highest to lowest.
SELECT first_name,last_name,specialization,consultation_fee,
ROW_NUMBER() OVER (ORDER BY consultation_fee DESC) AS rnk
FROM Specialists;

#13. Rank specialists based on consultation fee within each specialization.
SELECT first_name,last_name,specialization,consultation_fee,
ROW_NUMBER() OVER (PARTITION BY specialization ORDER BY consultation_fee DESC) AS rnk
FROM Specialists;

#14. Display the previous consultation fee for each specialist.
SELECT first_name,last_name,specialization,consultation_fee,
LAG(consultation_fee) OVER (ORDER BY consultation_fee DESC) 
FROM Specialists;

# 15. Display the next consultation fee for each specialist.
SELECT first_name,last_name,specialization,consultation_fee,
LEAD(consultation_fee) OVER (ORDER BY consultation_fee DESC) 
FROM Specialists;

# 16. What is the total number of members
SELECT COUNT(*) AS Total_Members
FROM Members;

#17. What is the average bill value
SELECT ROUND(AVG(total_amount), 2) AS Average_Bill_Value
FROM Billing;

#18. How many consultations are there?
SELECT COUNT(*) AS Total_Consultations
FROM Consultations;

#19. How many consultations does each member have on average?
SELECT 
    ROUND(COUNT(c.consultation_id) / COUNT(DISTINCT m.member_id), 2)
        AS avg_consultations_per_member
FROM Members m
LEFT JOIN Consultations c
    ON m.member_id = c.member_id;
    
#20. Which reasons for visit are most common?
SELECT 
    reason_for_visit,
    COUNT(*) AS consultation_count
FROM Consultations
GROUP BY reason_for_visit
ORDER BY consultation_count DESC;

# 21. How many consultations have associated telemedicine sessions?
SELECT 
    COUNT(DISTINCT t.consultation_id) AS consultations_with_telemedicine
FROM Telemedicine_Sessions t;

#22. Which chronic conditions have the highest enrollment?
SELECT 
    condition_name,
    COUNT(*) AS program_count
FROM Chronic_Care_Programs
GROUP BY condition_name
ORDER BY program_count DESC;

#23. What is the payment-status distribution of package subscriptions?
SELECT 
    payment_status,
    COUNT(*) AS subscription_count
FROM Package_Subscriptions
GROUP BY payment_status
ORDER BY subscription_count DESC;

#24. Which industries have the greatest corporate participation?
SELECT 
    co.industry,
    COUNT(DISTINCT co.corporate_id) AS corporate_count,
    COUNT(cm.member_id) AS enrolled_members
FROM Corporates co
LEFT JOIN Corporate_Members cm
    ON co.corporate_id = cm.corporate_id
GROUP BY co.industry
ORDER BY enrolled_members DESC;

#25. Which medicines are prescribed most frequently?
SELECT 
    medicine_name,
    COUNT(*) AS prescription_count
FROM Prescriptions
GROUP BY medicine_name
ORDER BY prescription_count DESC
LIMIT 10;

#26. Which lab tests generate the highest total cost?
SELECT 
    test_name,
    COUNT(*) AS test_count,
    ROUND(SUM(test_cost), 2) AS total_test_cost
FROM Lab_Tests
GROUP BY test_name
ORDER BY total_test_cost DESC;

#27. What is the total and average claim amount?
SELECT
    COUNT(*) AS total_claims,
    ROUND(SUM(claim_amount), 2) AS total_claim_amount,
    ROUND(AVG(claim_amount), 2) AS average_claim_amount
FROM Claims;

#28. What is the total payment amount by payment status?
SELECT 
    payment_status,
    COUNT(*) AS payment_count,
    ROUND(SUM(payment_amount), 2) AS total_payment_amount
FROM Payments
GROUP BY payment_status
ORDER BY total_payment_amount DESC;

#21. What is the average consultation rating?
SELECT 
    ROUND(AVG(rating), 2) AS average_rating
FROM Feedback;

#22.How many staff members work in each clinic?
SELECT 
    cl.clinic_name,
    COUNT(s.staff_id) AS staff_count
FROM Clinics cl
LEFT JOIN Staff s
    ON cl.clinic_id = s.clinic_id
GROUP BY cl.clinic_name
ORDER BY staff_count DESC;